//
//  PowerJackProgressionSeedScenario.swift
//  PowerJack
//
//  Week 1 fully logged with feedback; week 2 generated by the real Build planner.
//

import SwiftData

struct PowerJackProgressionSeedScenario {
    let container: ModelContainer
    let program: Program
    let weekOneWorkouts: [Workout]
    let weekTwoWorkouts: [Workout]
    /// Week 2's squat, held behind a manual check-in after severe pain in week 1.
    let checkInExercise: WorkoutExercise
}

extension PowerJackSeed {
    /// Logged performance for one week-1 exercise: (reps, weight in tenths of a pound) per set.
    private struct SeedLog {
        let sets: [(reps: Int, weightTenthsPounds: Int?)]
        let repsLeft: RepsInReserve
        let pain: LevelOfPain
    }

    static func weekTwoProgression() -> PowerJackProgressionSeedScenario {
        let container = makeInMemoryContainer()
        let context = container.mainContext
        let exercises = makeExercises()
        let templateProgram = makeTemplateProgram(exercises: exercises)

        for exercise in exercises {
            context.insert(exercise)
        }
        context.insert(templateProgram)

        let program = Program(programLengthWeeks: 4, templateProgram: templateProgram)
        context.insert(program)
        program.start()

        // Keyed by template position: [day][exercise]. Week 1 calibrates, so week 2 is set from these.
        let logs: [[SeedLog]] = [
            [
                // Bench: 4 reps left where 3 were aimed for -> 140 lb for 12.
                SeedLog(sets: [(12, 1350), (11, 1350)], repsLeft: .four, pain: .none),
                // Squat: severe pain -> lighter, one set, behind a check-in.
                SeedLog(sets: [(8, 2250), (8, 2250)], repsLeft: .one, pain: .severe),
            ],
            [
                // Pull up (reps only): 7 reps with 2 left -> 8 reps, aiming for 1 left.
                SeedLog(sets: [(8, nil), (7, nil)], repsLeft: .two, pain: .mild),
                // Lat pulldown: 4 reps with 1 left is too heavy -> 110 lb for 7.
                SeedLog(sets: [(10, 1200), (4, 1200)], repsLeft: .one, pain: .none),
            ],
            [
                // Lateral raise: moderate pain -> held as it was.
                SeedLog(sets: [(12, 150), (12, 150)], repsLeft: .four, pain: .moderate),
                // Leg press: on target -> same weight and reps.
                SeedLog(sets: [(10, 3150), (10, 3150)], repsLeft: .two, pain: .none),
            ],
        ]

        let weekOneWorkouts = program.programWeeks[0].workouts
        for (workout, dayLogs) in zip(weekOneWorkouts, logs) {
            workout.startAndCascade()
            for (workoutExercise, log) in zip(workout.workoutExercises, dayLogs) {
                for warmup in workoutExercise.warmupSets {
                    warmup.complete()
                }
                for (workoutSet, entry) in zip(workoutExercise.workingSets, log.sets) {
                    workoutSet.reps = entry.reps
                    workoutSet.weightTenthsPounds = entry.weightTenthsPounds
                    workoutSet.complete()
                }
                workoutExercise.addFeedback(
                    feedback: ExerciseFeedback(repsInReserve: log.repsLeft, levelOfPain: log.pain)
                )
                workoutExercise.completeAndCascade()
            }
            program.finishWorkout(workout)
        }

        let weekTwoWorkouts = program.programWeeks[1].workouts
        let checkInExercise = weekTwoWorkouts[0].workoutExercises[1]

        do {
            try context.save()
        } catch {
            fatalError("Could not save seeded progression data: \(error)")
        }

        return PowerJackProgressionSeedScenario(
            container: container,
            program: program,
            weekOneWorkouts: weekOneWorkouts,
            weekTwoWorkouts: weekTwoWorkouts,
            checkInExercise: checkInExercise
        )
    }
}
